<?php require 'config.php'; role_required(['admin']);$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['act']??'';try{if($a==='add')$pdo->prepare('INSERT INTO departments(name,code) VALUES(?,?)')->execute([trim($_POST['name']),trim($_POST['code'])]);if($a==='delete')$pdo->prepare('DELETE FROM departments WHERE id=?')->execute([(int)$_POST['id']]);flash('ok','บันทึกเรียบร้อย');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('departments.php');}$msg=flash();$rows=$pdo->query('SELECT * FROM departments ORDER BY name')->fetchAll();?><!doctype html><html><head><?php include 'partials/head.php';?></head><body><?php include 'partials/nav.php';?><main class="container"><div class="page-head"><h2>🏢 จัดการแผนก</h2></div><?php if($msg):?><div class="alert <?=e($msg[0])?>"><?=e($msg[1])?></div><?php endif;?><form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="act" value="add"><div class="row"><div><label>ชื่อแผนก</label><input name="name" required></div><div><label>รหัสแผนก</label><input name="code"></div></div><br><button>＋ เพิ่มแผนก</button></form><div class="panel"><table class="table"><tr><th>ชื่อแผนก</th><th>รหัส</th><th></th></tr><?php foreach($rows as $d):?><tr><td><?=e($d['name'])?></td><td><?=e($d['code'])?></td><td><form method="post" onsubmit="return confirm('ลบแผนกนี้?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="act" value="delete"><input type="hidden" name="id" value="<?=$d['id']?>"><button class="danger">ลบ</button></form></td></tr><?php endforeach;?></table></div></main></div></div></body></html>